\def\face{\draw (0,0) circle (2.3);\draw[line width=0.4pt] (-0.8,0.6) ellipse (0.55 and 0.75);\draw[line width=0.4pt] (0.8,0.6) ellipse (0.55 and 0.75);\fill (-0.8,0.6) circle (0.2);\fill (0.8,0.6) circle (0.2);\draw[line width=0.4pt] (-1.25,-0.55) .. controls (-0.7,-1.7) and (0.7,-1.7) .. (1.25,-0.55);}
